def _sorted4(a, b, c, d):
    # Independent insertion sort of the four inputs
    xs = [a, b, c, d]
    n = 4
    for i in range(1, n):
        j = i
        while j > 0 and xs[j - 1] > xs[j]:
            tmp = xs[j - 1]
            xs[j - 1] = xs[j]
            xs[j] = tmp
            j -= 1
    return xs


def post(a, b, c, d, result):
    if not isinstance(result, tuple):
        return False
    if len(result) != 4:
        return False
    s = _sorted4(a, b, c, d)
    return (result[0] == s[0] and result[1] == s[1]
            and result[2] == s[2] and result[3] == s[3])
